102	<div class="wrap">
103	  <h1>Claude Code Runner</h1>
104	  <div class="sub">Send a prompt to the <code>claude</code> CLI, running against a working directory you choose. Only one prompt runs at a time.</div>
105	
106	  <div class="error-banner" id="errorBanner"></div>
107	
108	  <div class="panel">
109	    <div class="field">
110	      <label for="cwd">Working directory (absolute or relative path)</label>
111	      <input type="text" id="cwd" placeholder="/Users/you/projects/my-repo" />
112	    </div>
113	    <div class="field">
114	      <label for="prompt">Prompt</label>
115	      <textarea id="prompt" placeholder="e.g. Add a health check endpoint to the server"></textarea>
116	    </div>
117	    <div class="field checkbox-row">
118	      <input type="checkbox" id="bypass" />
119	      <label for="bypass" style="margin:0;">
120	        <strong>Bypass permission prompts</strong> — lets Claude edit files and run commands in this
121	        directory without asking. Only enable this for directories you trust.
122	      </label>
123	    </div>
124	    <div class="row">
125	      <button id="runBtn">Run</button>
126	      <button id="stopBtn" disabled>Stop</button>
127	    </div>
128	  </div>
129	
130	  <div class="status-line">
131	    <span class="dot" id="statusDot"></span>
132	    <span id="statusText">Idle</span>
133	  </div>
134	
135	  <div id="output"></div>
136	</div>
137	
138	<script>
139	const cwdInput = document.getElementById('cwd');
140	const promptInput = document.getElementById('prompt');
141	const bypassInput = document.getElementById('bypass');
142	const runBtn = document.getElementById('runBtn');
143	const stopBtn = document.getElementById('stopBtn');
144	const output = document.getElementById('output');
145	const statusDot = document.getElementById('statusDot');
146	const statusText = document.getElementById('statusText');
147	const errorBanner = document.getElementById('errorBanner');
148	
149	function showError(msg) {
150	  errorBanner.textContent = msg;
151	  errorBanner.style.display = msg ? 'block' : 'none';
152	}
153	
154	function setRunning(running) {
155	  runBtn.disabled = running;
156	  stopBtn.disabled = !running;
157	  cwdInput.disabled = running;
158	  promptInput.disabled = running;
159	  bypassInput.disabled = running;
160	  statusDot.className = 'dot' + (running ? ' running' : '');
161	  statusText.textContent = running ? 'Running…' : 'Idle';
162	}
163	
164	function appendOutput(chunk, isStderr) {
165	  const span = document.createElement('span');
166	  if (isStderr) span.className = 'stderr';
167	  span.textContent = chunk;
168	  output.appendChild(span);
169	  output.scrollTop = output.scrollHeight;
170	}
171	
172	async function refreshStatus() {
173	  try {
174	    const res = await fetch('/api/status');
175	    const s = await res.json();
176	    setRunning(s.running);
177	  } catch {}
178	}
179	
180	runBtn.addEventListener('click', async () => {
181	  showError('');
182	  const cwd = cwdInput.value.trim();
183	  const prompt = promptInput.value.trim();
184	  if (!cwd) return showError('Please enter a working directory.');
185	  if (!prompt) return showError('Please enter a prompt.');
186	
187	  output.textContent = '';
188	  setRunning(true);
189	
190	  const res = await fetch('/api/run', {
191	    method: 'POST',
192	    headers: { 'Content-Type': 'application/json' },
193	    body: JSON.stringify({ cwd, prompt, bypassPermissions: bypassInput.checked }),
194	  });
195	
196	  if (!res.ok) {
197	    const err = await res.json().catch(() => ({}));
198	    showError(err.error || `Request failed (${res.status})`);
199	    setRunning(false);
200	  }
201	});
202	
203	stopBtn.addEventListener('click', async () => {
204	  await fetch('/api/stop', { method: 'POST' });
205	});
206	
207	const es = new EventSource('/api/stream');
208	
209	es.addEventListener('status', (e) => {
210	  const s = JSON.parse(e.data);
211	  setRunning(s.running);
212	  if (s.running && s.prompt && promptInput.value.trim() === '') {
213	    // another client started a run; reflect it here
214	    cwdInput.value = s.cwd || '';
215	    promptInput.value = s.prompt || '';
216	  }
217	});
218	
219	es.addEventListener('output', (e) => {
220	  const data = JSON.parse(e.data);
221	  appendOutput(data.chunk, !!data.stderr);
222	});
223	
224	es.addEventListener('done', (e) => {
225	  const data = JSON.parse(e.data);
226	  setRunning(false);
227	  statusText.textContent = data.exitCode === 0 ? 'Done' : `Exited (code ${data.exitCode})`;
228	  if (data.exitCode !== 0) statusDot.classList.add('error');
229	  else statusDot.classList.remove('error');
230	});
231	
232	refreshStatus();
233	</script>
234	</body>
235	</html>
