#!/usr/bin/env node
'use strict';

const http = require('http');
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

const PORT = process.env.PORT || 4756;
const PUBLIC_DIR = path.join(__dirname, 'public');

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
};

// --- single-job state -------------------------------------------------

const state = {
  running: false,
  proc: null,
  cwd: null,
  prompt: null,
  startedAt: null,
  exitCode: null,
  history: [], // buffered output chunks, replayed to clients that connect mid-run
};

const clients = new Set(); // open SSE responses

function publicState() {
  return {
    running: state.running,
    cwd: state.cwd,
    prompt: state.prompt,
    startedAt: state.startedAt,
    exitCode: state.exitCode,
  };
}

function sseWrite(res, event, data) {
  res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

function broadcast(event, data) {
  for (const res of clients) sseWrite(res, event, data);
}

function startRun({ prompt, cwd, bypassPermissions }, res) {
  if (state.running) {
    return sendJSON(res, 409, { error: 'A prompt is already running. Wait for it to finish or stop it first.' });
  }
  if (typeof prompt !== 'string' || !prompt.trim()) {
    return sendJSON(res, 400, { error: 'Prompt is required.' });
  }
  if (typeof cwd !== 'string' || !cwd.trim()) {
    return sendJSON(res, 400, { error: 'Working directory is required.' });
  }

  const resolvedCwd = path.resolve(cwd.trim());
  let stat;
  try {
    stat = fs.statSync(resolvedCwd);
  } catch {
    return sendJSON(res, 400, { error: `Directory does not exist: ${resolvedCwd}` });
  }
  if (!stat.isDirectory()) {
    return sendJSON(res, 400, { error: `Not a directory: ${resolvedCwd}` });
  }

  const args = ['-p', prompt, '--output-format', 'text'];
  if (bypassPermissions) args.push('--permission-mode', 'bypassPermissions');

  let proc;
  try {
    proc = spawn('claude', args, { cwd: resolvedCwd, env: process.env, stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (err) {
    return sendJSON(res, 500, { error: `Failed to launch claude: ${err.message}` });
  }

  state.running = true;
  state.proc = proc;
  state.cwd = resolvedCwd;
  state.prompt = prompt;
  state.startedAt = new Date().toISOString();
  state.exitCode = null;
  state.history = [];

  broadcast('status', publicState());

  proc.stdout.on('data', (d) => {
    const chunk = d.toString();
    state.history.push(chunk);
    broadcast('output', { chunk });
  });
  proc.stderr.on('data', (d) => {
    const chunk = d.toString();
    state.history.push(chunk);
    broadcast('output', { chunk, stderr: true });
  });
  proc.on('close', (code) => {
    state.running = false;
    state.proc = null;
    state.exitCode = code;
    broadcast('done', { exitCode: code });
    broadcast('status', publicState());
  });
  proc.on('error', (err) => {
    const chunk = `\n[error running claude: ${err.message}]\n`;
    state.history.push(chunk);
    broadcast('output', { chunk, stderr: true });
    state.running = false;
    state.proc = null;
    state.exitCode = -1;
    broadcast('done', { exitCode: -1 });
    broadcast('status', publicState());
  });

  return sendJSON(res, 202, { ok: true, ...publicState() });
}

// --- tiny http plumbing -------------------------------------------------

function sendJSON(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function serveStatic(req, res, urlPath) {
  const rel = urlPath === '/' ? '/index.html' : urlPath;
  const filePath = path.normalize(path.join(PUBLIC_DIR, rel));
  if (!filePath.startsWith(PUBLIC_DIR)) {
    res.writeHead(403);
    return res.end('Forbidden');
  }
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      return res.end('Not found');
    }
    const ext = path.extname(filePath);
    res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
    res.end(data);
  });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (req.method === 'GET' && url.pathname === '/api/status') {
    return sendJSON(res, 200, publicState());
  }

  if (req.method === 'GET' && url.pathname === '/api/stream') {
    res.writeHead(200, {
      'Content-Type': 'text/event-stream; charset=utf-8',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    });
    res.write(': connected\n\n');
    sseWrite(res, 'status', publicState());
    if (state.history.length) {
      sseWrite(res, 'output', { chunk: state.history.join('') });
    }
    clients.add(res);
    req.on('close', () => clients.delete(res));
    return;
  }

  if (req.method === 'POST' && url.pathname === '/api/run') {
    let body = '';
    req.on('data', (c) => {
      body += c;
      if (body.length > 1e6) req.destroy(); // guard against runaway bodies
    });
    req.on('end', () => {
      let data;
      try {
        data = JSON.parse(body || '{}');
      } catch {
        return sendJSON(res, 400, { error: 'Invalid JSON body.' });
      }
      startRun(data, res);
    });
    return;
  }

  if (req.method === 'POST' && url.pathname === '/api/stop') {
    if (state.running && state.proc) {
      state.proc.kill('SIGTERM');
      return sendJSON(res, 200, { ok: true });
    }
    return sendJSON(res, 200, { ok: false, message: 'Nothing is running.' });
  }

  if (req.method === 'GET') {
    return serveStatic(req, res, url.pathname);
  }

  res.writeHead(404);
  res.end('Not found');
});

server.listen(PORT, () => {
  console.log(`Claude Code runner UI: http://localhost:${PORT}`);
});

#!/usr/bin/env node
'use strict';

const http = require('http');
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

const PORT = process.env.PORT || 4756;
const PUBLIC_DIR = path.join(__dirname, 'public');

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
};

// --- single-job state -------------------------------------------------

const state = {
  running: false,
  proc: null,
  cwd: null,
  prompt: null,
  startedAt: null,
  exitCode: null,
  trajectory: [], // structured trajectory items, replayed to clients that connect mid-run
  stdoutBuffer: '', // partial line carried over between stdout chunks
};

const clients = new Set(); // open SSE responses

function publicState() {
  return {
    running: state.running,
    cwd: state.cwd,
    prompt: state.prompt,
    startedAt: state.startedAt,
    exitCode: state.exitCode,
  };
}

function sseWrite(res, event, data) {
  res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

function broadcast(event, data) {
  for (const res of clients) sseWrite(res, event, data);
}

function emitTrajectory(item) {
  item.ts = new Date().toISOString();
  state.trajectory.push(item);
  broadcast('trajectory', item);
}

// Turn one parsed `claude --output-format stream-json` line into trajectory
// items: the assistant's text as it's produced, and every tool call with its
// name and input, each broadcast the moment it appears in the stream.
function processStreamEvent(evt) {
  if (evt.type === 'assistant' && evt.message && Array.isArray(evt.message.content)) {
    for (const block of evt.message.content) {
      if (block.type === 'text' && block.text) {
        emitTrajectory({ kind: 'text', text: block.text });
      } else if (block.type === 'tool_use') {
        emitTrajectory({ kind: 'tool_call', name: block.name, input: block.input });
      }
    }
  }
}

function consumeStdoutChunk(chunk) {
  state.stdoutBuffer += chunk;
  let idx;
  while ((idx = state.stdoutBuffer.indexOf('\n')) !== -1) {
    const line = state.stdoutBuffer.slice(0, idx).trim();
    state.stdoutBuffer = state.stdoutBuffer.slice(idx + 1);
    if (!line) continue;
    parseAndProcessLine(line);
  }
}

function parseAndProcessLine(line) {
  let evt;
  try {
    evt = JSON.parse(line);
  } catch {
    emitTrajectory({ kind: 'raw', text: line });
    return;
  }
  processStreamEvent(evt);
}

function startRun({ prompt, cwd, bypassPermissions }, res) {
  if (state.running) {
    return sendJSON(res, 409, { error: 'A prompt is already running. Wait for it to finish or stop it first.' });
  }
  if (typeof prompt !== 'string' || !prompt.trim()) {
    return sendJSON(res, 400, { error: 'Prompt is required.' });
  }
  if (typeof cwd !== 'string' || !cwd.trim()) {
    return sendJSON(res, 400, { error: 'Working directory is required.' });
  }

  const resolvedCwd = path.resolve(cwd.trim());
  let stat;
  try {
    stat = fs.statSync(resolvedCwd);
  } catch {
    return sendJSON(res, 400, { error: `Directory does not exist: ${resolvedCwd}` });
  }
  if (!stat.isDirectory()) {
    return sendJSON(res, 400, { error: `Not a directory: ${resolvedCwd}` });
  }

  const args = ['-p', prompt, '--output-format', 'text'];
  if (bypassPermissions) args.push('--permission-mode', 'bypassPermissions');

  let proc;
  try {
    proc = spawn('claude', args, { cwd: resolvedCwd, env: process.env, stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (err) {
    return sendJSON(res, 500, { error: `Failed to launch claude: ${err.message}` });
  }

  state.running = true;
  state.proc = proc;
  state.cwd = resolvedCwd;
  state.prompt = prompt;
  state.startedAt = new Date().toISOString();
  state.exitCode = null;
  state.history = [];

  broadcast('status', publicState());

  proc.stdout.on('data', (d) => {
    const chunk = d.toString();
    state.history.push(chunk);
    broadcast('output', { chunk });
  });
  proc.stderr.on('data', (d) => {
    const chunk = d.toString();
    state.history.push(chunk);
    broadcast('output', { chunk, stderr: true });
  });
  proc.on('close', (code) => {
    state.running = false;
    state.proc = null;
    state.exitCode = code;
    broadcast('done', { exitCode: code });
    broadcast('status', publicState());
  });
  proc.on('error', (err) => {
    const chunk = `\n[error running claude: ${err.message}]\n`;
    state.history.push(chunk);
    broadcast('output', { chunk, stderr: true });
    state.running = false;
    state.proc = null;
    state.exitCode = -1;
    broadcast('done', { exitCode: -1 });
    broadcast('status', publicState());
  });

  return sendJSON(res, 202, { ok: true, ...publicState() });
}

// --- tiny http plumbing -------------------------------------------------

function sendJSON(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function serveStatic(req, res, urlPath) {
  const rel = urlPath === '/' ? '/index.html' : urlPath;
  const filePath = path.normalize(path.join(PUBLIC_DIR, rel));
  if (!filePath.startsWith(PUBLIC_DIR)) {
    res.writeHead(403);
    return res.end('Forbidden');
  }
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      return res.end('Not found');
    }
    const ext = path.extname(filePath);
    res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
    res.end(data);
  });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (req.method === 'GET' && url.pathname === '/api/status') {
    return sendJSON(res, 200, publicState());
  }

  if (req.method === 'GET' && url.pathname === '/api/stream') {
    res.writeHead(200, {
      'Content-Type': 'text/event-stream; charset=utf-8',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    });
    res.write(': connected\n\n');
    sseWrite(res, 'status', publicState());
    if (state.history.length) {
      sseWrite(res, 'output', { chunk: state.history.join('') });
    }
    clients.add(res);
    req.on('close', () => clients.delete(res));
    return;
  }

  if (req.method === 'POST' && url.pathname === '/api/run') {
    let body = '';
    req.on('data', (c) => {
      body += c;
      if (body.length > 1e6) req.destroy(); // guard against runaway bodies
    });
    req.on('end', () => {
      let data;
      try {
        data = JSON.parse(body || '{}');
      } catch {
        return sendJSON(res, 400, { error: 'Invalid JSON body.' });
      }
      startRun(data, res);
    });
    return;
  }

  if (req.method === 'POST' && url.pathname === '/api/stop') {
    if (state.running && state.proc) {
      state.proc.kill('SIGTERM');
      return sendJSON(res, 200, { ok: true });
    }
    return sendJSON(res, 200, { ok: false, message: 'Nothing is running.' });
  }

  if (req.method === 'GET') {
    return serveStatic(req, res, url.pathname);
  }

  res.writeHead(404);
  res.end('Not found');
});

server.listen(PORT, () => {
  console.log(`Claude Code runner UI: http://localhost:${PORT}`);
});

