input.new_string:
function formatToolInput(input) {
  if (input == null) return '';
  if (typeof input !== 'object') return String(input);
  return Object.entries(input)
    .map(([key, value]) => {
      const text = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
      return key + ': ' + text;
    })
    .join('\n');
}

function renderTrajectoryItem(item) {
  const el = document.createElement('div');
  el.className = 'traj-item traj-' + item.kind;

  if (item.kind === 'text') {
    const label = document.createElement('div');
    label.className = 'traj-label';
    label.textContent = 'Assistant';
    const body = document.createElement('div');
    body.className = 'traj-text';
    body.textContent = item.text;
    el.append(label, body);
  } else if (item.kind === 'tool_call') {
    const label = document.createElement('div');
    label.className = 'traj-label';
    label.textContent = 'Tool call: ' + item.name;
    const body = document.createElement('pre');
    body.className = 'traj-input';
    body.textContent = formatToolInput(item.input);
    el.append(label, body);
  } else if (item.kind === 'stderr' || item.kind === 'raw') {
    el.classList.add('traj-error');
    el.textContent = item.text;
  } else {
    return; // unrecognized event kind, nothing to show
  }

  output.appendChild(el);
  output.scrollTop = output.scrollHeight;
}

