const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 900, height: 900 } });
  const consoleErrors = [];
  page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
  page.on('pageerror', (err) => consoleErrors.push('pageerror: ' + err.message));

  await page.goto('http://localhost:4756');
  await page.fill('#cwd', '/Users/jiannaso/Documents/github/cs2680/a1');
  await page.fill('#prompt', 'Read hello.py and summarize what it does in one sentence. Do not modify anything.');
  await page.check('#bypass');
  await page.click('#runBtn');

  // Screenshot partway through, after at least one trajectory item has rendered.
  await page.waitForSelector('#output .traj-item', { timeout: 30000 });
  await page.waitForTimeout(800);
  await page.screenshot({ path: 'mid-run.png' });
  const midHtml = await page.$eval('#output', (el) => el.innerHTML);

  // Wait for completion.
  await page.waitForFunction(() => document.getElementById('statusText').textContent.startsWith('Done') ||
    document.getElementById('statusText').textContent.startsWith('Exited'), { timeout: 60000 });
  await page.waitForTimeout(300);
  await page.screenshot({ path: 'done.png' });
  const finalHtml = await page.$eval('#output', (el) => el.innerHTML);
  const statusText = await page.$eval('#statusText', (el) => el.textContent);

  console.log('STATUS_TEXT:', statusText);
  console.log('CONSOLE_ERRORS:', JSON.stringify(consoleErrors));
  console.log('--- MID RUN OUTPUT HTML ---');
  console.log(midHtml);
  console.log('--- FINAL OUTPUT HTML ---');
  console.log(finalHtml);

  await browser.close();
})().catch((err) => {
  console.error('DRIVER ERROR:', err);
  process.exit(1);
});

