// Wait for the run to actually finish server-side (exitCode set), polling from
// outside the page to avoid any browser fetch-caching ambiguity.
const deadline = Date.now() + 30000;
for (;;) {
  const s = await (await fetch('http://localhost:4756/api/status')).json();
  if (s.exitCode !== null) break;
  if (Date.now() > deadline) throw new Error('run did not finish in time');
  await new Promise((r) => setTimeout(r, 500));
}
